import type { VerbEntry } from "../domain/types";

/**
 * Verb inventory.
 *
 * Only what the rules cannot derive is stored: the infinitive, its Russian
 * meaning, and explicit `forms` overrides for irregular or spelling-changing
 * cells. Everything else is generated by `domain/conjugation`.
 *
 * `ruPresent` / `ruPastStem` fix the Russian cue where the Russian conjugator
 * would guess wrong (ходить → хожу, писать → пишу).
 */

/** Verbs whose only irregularity is the "c → qu / g → gu / z → c" preterite yo. */
function spellingPreterite(yo: string): VerbEntry["forms"] {
  return { preterite: { yo } };
}

