/* -------------------------------------------------------------------------- */
/* Which verbs are conjugated at which level                                  */
/* -------------------------------------------------------------------------- */

/**
 * The A1 conjugation core: 45 verbs.
 *
 * Roughly the fifty most frequent verbs account for about four fifths of all
 * verb use in everyday Spanish, and past that point the return per card drops
 * sharply. Conjugating all 110 verbs at A1 would mean 1320 cards, most of them
 * spent on words like `pertenecer` and `exceder` that a beginner will not say.
 *
 * Note the make-up: the most frequent verbs in Spanish are overwhelmingly
 * irregular, so eighteen of the forty-five are irregular — that is not a
 * difficulty setting, it is what the frequency list looks like. The rest of the
 * verbs stay fully available for meaning practice; only conjugation moves to A2.
 */
export const A1_REGULAR_VERB_IDS = [
  // -ar
  "v.pasar",
  "v.hablar",
  "v.llegar",
  "v.dejar",
  "v.quedar",
  "v.llamar",
  "v.tomar",
  "v.mirar",
  "v.buscar",
  "v.esperar",
  "v.trabajar",
  // -er
  "v.creer",
  "v.comer",
  "v.beber",
  "v.aprender",
  "v.comprender",
  "v.correr",
  "v.leer",
  "v.deber",
  "v.responder",
  // -ir
  "v.vivir",
  "v.escribir",
  "v.abrir",
  "v.recibir",
  "v.subir",
  "v.decidir",
  "v.permitir",
];

export const A1_IRREGULAR_VERB_IDS = [
  "v.ser",
  "v.estar",
  "v.ir",
  "v.tener",
  "v.hacer",
  "v.poder",
  "v.querer",
  "v.decir",
  "v.ver",
  "v.dar",
  "v.saber",
  "v.venir",
  "v.poner",
  "v.salir",
  "v.conocer",
  "v.pensar",
  "v.volver",
  "v.dormir",
];

const A1_CONJUGATION_SET = new Set([...A1_REGULAR_VERB_IDS, ...A1_IRREGULAR_VERB_IDS]);

/**
 * The irregulars as a conjugation deck, without `ser` and `estar`.
 *
 * Those two have a section of their own — telling them apart is a whole topic,
 * not one verb among eighteen — so drilling them here as well only meant
 * meeting the same cards twice. They stay in `A1_IRREGULAR_VERB_IDS` because
 * that list also decides what counts as A1 and what their meanings deck holds.
 */
export const A1_IRREGULAR_CONJUGATION_IDS = A1_IRREGULAR_VERB_IDS.filter(
  (id) => id !== "v.ser" && id !== "v.estar",
);

/** Everything not in the A1 core, split the same way, conjugated at A2. */
export const A2_REGULAR_VERB_IDS = [
  ...REGULAR_AR_VERBS,
  ...REGULAR_ER_VERBS,
  ...REGULAR_IR_VERBS,
]
  .filter((verb) => !A1_CONJUGATION_SET.has(verb.id))
  .map((verb) => verb.id);

export const A2_IRREGULAR_VERB_IDS = IRREGULAR_VERBS.filter(
  (verb) => !A1_CONJUGATION_SET.has(verb.id),
).map((verb) => verb.id);
